/**
 * Batch 10 — KP tables vs an INDEPENDENT Python implementation on Swiss Ephemeris.
 * Reference: golden/swissRef.json (golden/swiss_chalit_kp_jaimini_ref.py, pyswisseph 2.10.03):
 *   cusps  = swe.houses_ex(jd, lat, lon, b'P', FLG_SIDEREAL) with SIDM_KRISHNAMURTI;
 *   planets = calc_ut(…, FLG_SIDEREAL), SIDM_KRISHNAMURTI, mean node;
 *   sign/star/sub lords, KP house occupancy and 4-level significators recomputed in Python
 *   from their definitions (not from the TypeScript code).
 * golden/kp249.json: the 249-sub table generated by the same Python script.
 * Charts: P1, P3, P9 (round-2 panel). Two other panel charts are recorded as boundary cases.
 */
import { describe, it, expect } from 'vitest';
import ref from './golden/swissRef.json';
import t249 from './golden/kp249.json';
import { computeKp, kpSubTable, KP_SHIFT_DEG, SWISS_LAHIRI_MINUS_KP_ARCSEC } from '../kp';
import { housesSignified, kpSummary } from '../advancedText';
import { PANEL } from './panel';

type L = { sign: string; star: string; sub: string };
const R = ref as unknown as Record<string, { kp: {
  cusps: number[]; cuspLords: L[]; planets: Record<string, number>; planetLords: Record<string, L>;
  occupancy: Record<string, number>; significators: Record<string, { L1: string[]; L2: string[]; L3: string[]; L4: string[] }>;
} }>;
const arcmin = (a: number, b: number) => Math.abs(((a - b + 540) % 360) - 180) * 60;

describe('KP — cusps, lords and significators vs Swiss Ephemeris (SIDM_KRISHNAMURTI)', () => {
  for (const id of ['P1', 'P3', 'P9']) {
    it(`${id}: 12 Placidus cusps within 1′ and identical sign/star/sub lords`, () => {
      const { t, lat, lon } = PANEL[id];
      const kp = computeKp(t, lat, lon);
      kp.cusps.forEach((c, i) => {
        expect(arcmin(c.longitude, R[id].kp.cusps[i]), `${id} cusp ${i + 1}`).toBeLessThan(1);
        expect({ sign: c.sign, star: c.star, sub: c.sub }, `${id} cusp ${i + 1}`).toEqual(R[id].kp.cuspLords[i]);
      });
    });
    it(`${id}: planets within 1′, same lords, same KP house, same 4-level significators`, () => {
      const { t, lat, lon } = PANEL[id];
      const kp = computeKp(t, lat, lon);
      for (const p of kp.planets) {
        expect(arcmin(p.longitude, R[id].kp.planets[p.name]), p.name).toBeLessThan(1);
        expect({ sign: p.sign, star: p.star, sub: p.sub }, p.name).toEqual(R[id].kp.planetLords[p.name]);
        expect(p.house, p.name).toBe(R[id].kp.occupancy[p.name]);
      }
      for (const s of kp.significators) {
        const e = R[id].kp.significators[String(s.house)];
        expect([[...s.L1].sort(), [...s.L2].sort(), [...s.L3].sort(), s.L4], `house ${s.house}`).toEqual([e.L1, e.L2, e.L3, e.L4]);
      }
    });
  }

  it('P5 (London 1992): 3rd cusp lies 5″ from a sub boundary — flagged, not presented as certain', () => {
    // Swiss: Ketu sub; ours (16″ away): Venus sub. Both sides of the line → the page says so.
    const kp = computeKp(PANEL.P5.t, PANEL.P5.lat, PANEL.P5.lon);
    expect(kp.cusps[2].nearBoundary).toBe(true);
    expect(kp.cusps.filter(c => c.nearBoundary).map(c => c.house)).toEqual([3]);
  });

  it('KP ayanamsa = Swiss SIDM_KRISHNAMURTI: 348.67″ below Swiss Lahiri (+ the site’s 24.4″ Lahiri calibration)', () => {
    expect(SWISS_LAHIRI_MINUS_KP_ARCSEC).toBeCloseTo(348.668, 3);
    expect(KP_SHIFT_DEG * 3600).toBeCloseTo(373.068, 3);
  });

  it('cusp sub lords flag a ±2-minute birth-time change', () => {
    const kp = computeKp(PANEL.P1.t, PANEL.P1.lat, PANEL.P1.lon);
    expect(kp.cusps.some(c => c.timeSensitive)).toBe(true);
  });

  it('plain-language summary names the 7th/10th/11th cusp sub lords and the Mahadasha lord’s houses', () => {
    const kp = computeKp(PANEL.P1.t, PANEL.P1.lat, PANEL.P1.lon);
    const lines = kpSummary(kp, 'Saturn');
    expect(lines[0]).toContain(`7th cusp (marriage and partnerships) — ${kp.cusps[6].sub}`);
    expect(lines[1]).toContain(`houses ${housesSignified(kp).Saturn.join(', ')}`);
  });
});

describe('KP 249-sub table', () => {
  const rows = (t249 as { rows: Array<{ start: number; sign: string; star: string; sub: string }> }).rows;
  it('has exactly 249 subs (27 × 9 + 6 split by sign boundaries)', () => {
    expect(kpSubTable()).toHaveLength(249);
    expect(rows).toHaveLength(249);
  });
  it('matches the independent Python table row by row (start degree, sign, star and sub lord)', () => {
    kpSubTable().forEach((r, i) => {
      expect(r.start, `row ${i + 1}`).toBeCloseTo(rows[i].start, 6);
      expect([r.sign, r.star, r.sub], `row ${i + 1}`).toEqual([rows[i].sign, rows[i].star, rows[i].sub]);
    });
  });
  it('first rows: Aries 0° Ketu/Ketu, then Venus sub at 0°46′40″ (7/120 of 13°20′)', () => {
    const t = kpSubTable();
    expect([t[0].sign, t[0].star, t[0].sub]).toEqual(['Mars', 'Ketu', 'Ketu']);
    expect(t[1].start * 3600).toBeCloseTo(46 * 60 + 40, 3);
    expect(t[1].sub).toBe('Venus');
  });
});
